function ActivityMidFestivalMainDialog:GetActivityMidFestivalComponent()
    ---@type ActivityMidFestivalComponent
    local ActivityMidFestivalComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    return ActivityMidFestivalComponent
end

function ActivityMidFestivalMainDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.parameters = self.controller.Argument.parameters
        local activityDojo = self:GetActivityMidFestivalComponent():GetActivityDojo()
        local key = string.format("FirstAccessMidFestivalEntrance_%s",activityDojo.id)
        local isPlay = tonumber(CfUtils.GetLocalData(key, 0))
        local playPrologue = isNotNull(self.parameters) and checkBool(self.parameters.playPrologue)
        if playPrologue and isPlay == 0 then
            CfUtils.WriteLocalData(key, 1)
            local t = {}
            ---@type ActivityMidFestivalUtils
            local ActivityMidFestivalUtils = import("Game.Activity.MidFestival.ActivityMidFestivalUtils")
            ---@type MidFestivalActivityScheduleVo
            local planVo = ActivityMidFestivalUtils.GetActivityScheduleVo()
            table.insert(t, planVo.storyId)
            local playing = true
            ActivityMidFestivalMainQuestPlotTool.StartPlayPlot(t, function()
                playing = false
            end)
            while playing do
                coroutine.yield(Yielders.EndOfFrame)
            end
        end
        self._isWaiting = true
        if not self._isRequest then
            self:InitHandler()
            self:InitData()
            self._isRequest = true
        end 
        while self._isWaiting do
            coroutine.yield(Yielders.EndOfFrame)
        end
        ActivityMidFestivalMgr:PlayBgMusic()
    end))
    return coWait
end

function ActivityMidFestivalMainDialog:PlayMainBGM()
    GameUtils.PlayMainBGM()
    UIModule.BackDialog()
end

function ActivityMidFestivalMainDialog:OnFocus(focus)
    if focus then
        CfUtils.SetTopCommonCb(Bind(self, self.PlayMainBGM))
        local coinId = self:GetActivityMidFestivalComponent():GetActivityCoinId()
        local energyId = self:GetActivityMidFestivalComponent():GetActivityEnergyId()
        CfUtils.RefreshTopGoods({energyId,coinId})
    else
        CfUtils.ResetNavigatorCustomBackAction()
    end
end

