function ActivityMidFestivalMainDialog:InitHandler()
    ---@type UINavigatorBar
    local navigatorEnv = CfUtils.GetLuaScr(CS.UINavigationBarRoot.Instance.gameObject, "Game.Main.UINavigatorBar")

    self.events[Constants.EventNames.MidFestivalHomeReq] = Events.AddListener(Constants.EventNames.MidFestivalHomeReq, Bind(self, self.HomeReqHandler))
    self.events[Constants.EventNames.EveryThingChangeEventName] = Events.AddListener(Constants.EventNames.EveryThingChangeEventName, Bind(self, self.OnBuyStaminaCallback))
    SetButtonAction(self.BtnDesc, Bind(self, self.OnClickBtnDescHandler))
end

function ActivityMidFestivalMainDialog:InitData()
    self:GetActivityMidFestivalComponent():HomeReq()
end
