--region handler
function ActivityMidFestivalMainDialog:HomeReqHandler()
    self._isWaiting = false
    self._homeDojo = self:GetActivityMidFestivalComponent():GetHomeDojo()

    ---@type MidFestivalActivityParameterVo
    local parametersVo = CfUtils.GetCf(AutoIds.IdSetting6084, "MidFestivalActivityParameterVo", true)
    self._recoverySeconds = checkNumber(parametersVo[1].num)   -- 恢复活动体力所需秒数
    self._recoveryCountPerTime = checkNumber(parametersVo[2].num)   -- 活动体力每次恢复X点
    self:RefreshUI()
end

function ActivityMidFestivalMainDialog:OnClickBtnDescHandler()
    CfUtils.ShowModuleToast(checkNumber(self._homeDojo.scheduleConf.ruleId))
end

function ActivityMidFestivalMainDialog:OnBuyStaminaCallback()
    -- 强制设置为服务器数量
    local hpData = self:GetActivityMidFestivalComponent():GetHomeDojo().hpData
    if isNull(hpData) then
        return
    end
    local serverHp = checkNumber(hpData.hp) -- 服务器中体力的数量
    local energyId = self:GetActivityMidFestivalComponent():GetActivityEnergyId()
    local curCount = checkNumber(GoodsUtils.GetThingNo(energyId))
    local deltaCount = serverHp - curCount
    GoodsUtils.DrawRewards({
        {
            goodsId = energyId,
            num = deltaCount
        }
    } , false)

    CfUtils.RefreshTopGoods()
end
--endregion handler

